import math

BASE_PRICES = {"domestic": 5.00, "eu": 12.00, "intl": 25.00}
EXTRA_KG_PRICE = 2.00
FREE_MAX_KG = 0.5


def shipping_cost(weight_kg: float, zone: str, express: bool = False) -> float:
    if zone not in BASE_PRICES:
        raise ValueError(f"unknown zone: {zone!r}")
    if not weight_kg > 0:
        raise ValueError(f"weight_kg must be > 0, got {weight_kg!r}")

    if zone == "domestic" and not express and weight_kg <= FREE_MAX_KG:
        return 0.00

    extra_kg = max(0, math.ceil(weight_kg - 1))
    total = BASE_PRICES[zone] + extra_kg * EXTRA_KG_PRICE
    if express:
        total *= 2
    return round(total, 2)

