import pytest

import shipping


def test_module_imports():
    assert hasattr(shipping, "shipping_cost")


@pytest.mark.parametrize(
    "zone, expected",
    [("domestic", 5.00), ("eu", 12.00), ("intl", 25.00)],
)
def test_base_price_by_zone(zone, expected):
    assert shipping.shipping_cost(1.0, zone) == expected


@pytest.mark.parametrize("zone", ["", "DOMESTIC", "us", "mars"])
def test_unknown_zone_raises(zone):
    with pytest.raises(ValueError):
        shipping.shipping_cost(1.0, zone)


@pytest.mark.parametrize("weight", [0, 0.0, -1, -0.5, float("nan")])
def test_non_positive_weight_raises(weight):
    with pytest.raises(ValueError):
        shipping.shipping_cost(weight, "eu")


@pytest.mark.parametrize(
    "weight, expected",
    [
        (1.0, 0.00),
        (1.2, 2.00),
        (2.0, 2.00),
        (3.0, 4.00),
        (3.1, 6.00),
    ],
)
def test_every_started_kg_above_first_adds_2(weight, expected):
    assert shipping.shipping_cost(weight, "intl") - 25.00 == pytest.approx(expected)


def test_express_doubles_total():
    assert shipping.shipping_cost(3.1, "eu", express=True) == 2 * (12.00 + 6.00)


@pytest.mark.parametrize("weight", [0.1, 0.5])
def test_domestic_light_non_express_is_free(weight):
    assert shipping.shipping_cost(weight, "domestic") == 0.00


def test_domestic_light_express_is_not_free():
    assert shipping.shipping_cost(0.5, "domestic", express=True) == 10.00


def test_domestic_just_over_half_kg_is_charged():
    assert shipping.shipping_cost(0.6, "domestic") == 5.00


def test_non_domestic_light_is_not_free():
    assert shipping.shipping_cost(0.5, "eu") == 12.00


def test_result_is_rounded_to_two_decimals():
    assert shipping.shipping_cost(1.0, "intl", express=True) == 50.00
    assert isinstance(shipping.shipping_cost(2.5, "eu"), float)

